       kategori, placering, enhed)
where not exists (
  select 1 from materialer m
  where (m.elnr is not null and m.elnr <> '' and m.elnr = v.elnr)
     or (m.type_da = v.type_da and coalesce(m.model,'') = coalesce(v.model,''))
);

-- To rækker i regnearket har en ugyldig kategorikode (kyrillisk 'А' og en tom).
-- De ligger nu uden kategori — find dem i appen med filteret "Uden kategori".

-- ---------- 10. Historik pr. vare, med løbende saldo ----------
-- Svarer til det appen viser når man klikker på en vare i lageret.
create or replace view v_historik as
select b.materiale_id, b.dato, b.art, b.antal, b.initialer, b.note, b.afdeling,
       u.navn as udstyr,
       sum(b.antal) over (partition by b.materiale_id, b.afdeling
                          order by b.dato, b.id) as saldo
from bevaegelser b
left join udstyr u on u.id = b.udstyr_id
order by b.materiale_id, b.dato, b.id;

-- ============================================================
--  11. Udstyr: 2630 rækker — 1943 tavle, 217 lystårn, 169 køletrailer, 79 generator, 60 køle-fryse modul, 56 led-strip, 30 kabel, 22 batteri, 16 adapter, 16 powerlock, 11 tilbehør, 5 kabelopruller, 3 omformer, 2 trailer, 1 måler.
--
--      To slags rækker:
--      1) Anlægsaktiver fra BC. navn = anlægsnummer, én række pr. fysisk enhed.
--         Solgte er udeladt; 'Ja - Reparation' og 'Ja - Savnet' er med.
--         Stavemåden er ensrettet pr. ressourcenr., og varenummeret fjernet
--         fra teksten ('PDU 63A NR 57122' -> 'PDU 63A').
--      2) Kabler, powerlock og adaptere fra prislisten. De har intet
--         anlægsnummer, så navn = varenummer og forbruget opgøres pr. varetype.
--         Vil I have dem pr. stk., skal de først mærkes fysisk.
-- ============================================================
insert into udstyr (navn, type, model, ressourcenr, serienr, afdeling)
select v.navn, v.type, v.model, v.ressourcenr, v.serienr, v.afdeling
from (values
